class Solution {
    public int largestClearPlot(char[][] land) {
        int R = land.length, C = land[0].length;
        int best = 0;
        for (int r1 = 0; r1 < R; r1++)
            for (int c1 = 0; c1 < C; c1++)
                for (int r2 = r1; r2 < R; r2++)
                    for (int c2 = c1; c2 < C; c2++) {
                        boolean clear = true;
                        for (int r = r1; r <= r2 && clear; r++)
                            for (int c = c1; c <= c2 && clear; c++)
                                if (land[r][c] != '1') clear = false;
                        if (clear) best = Math.max(best, (r2 - r1 + 1) * (c2 - c1 + 1));
                    }
        return best;
    }
}

