class Solution:
    def largestClearPlot(self, land: List[List[str]]) -> int:
        C = len(land[0])
        h = [0] * (C + 1)
        best = 0
        for row in land:
            for c in range(C):
                h[c] = h[c] + 1 if row[c] == "1" else 0
            stack = []
            for i in range(C + 1):
                while stack and h[stack[-1]] >= h[i]:
                    height = h[stack.pop()]
                    width = i - stack[-1] - 1 if stack else i
                    best = max(best, height * width)
                stack.append(i)
        return best

