class Solution {
    public int largestClearPlot(char[][] land) {
        int C = land[0].length;
        int[] h = new int[C + 1], stack = new int[C + 1];
        int best = 0;
        for (char[] row : land) {
            for (int c = 0; c < C; c++) h[c] = row[c] == '1' ? h[c] + 1 : 0;
            int top = 0;
            for (int i = 0; i <= C; i++) {
                while (top > 0 && h[stack[top - 1]] >= h[i]) {
                    int height = h[stack[--top]];
                    int width = top > 0 ? i - stack[top - 1] - 1 : i;
                    best = Math.max(best, height * width);
                }
                stack[top++] = i;
            }
        }
        return best;
    }
}

