class Solution {
public:
    int largestClearPlot(vector<vector<char>>& land) {
        int C = land[0].size();
        vector<int> h(C + 1, 0), stack;
        int best = 0;
        for (auto& row : land) {
            for (int c = 0; c < C; c++) h[c] = row[c] == '1' ? h[c] + 1 : 0;
            stack.clear();
            for (int i = 0; i <= C; i++) {
                while (!stack.empty() && h[stack.back()] >= h[i]) {
                    int height = h[stack.back()];
                    stack.pop_back();
                    int width = stack.empty() ? i : i - stack.back() - 1;
                    best = max(best, height * width);
                }
                stack.push_back(i);
            }
        }
        return best;
    }
};

