int largestClearPlot(char** land, int landSize, int* landColSize) {
    int C = landColSize[0];
    int* h = calloc(C + 1, sizeof(int));
    int* stack = malloc((C + 1) * sizeof(int));
    int best = 0;
    for (int r = 0; r < landSize; r++) {
        for (int c = 0; c < C; c++) h[c] = land[r][c] == '1' ? h[c] + 1 : 0;
        int top = 0;
        for (int i = 0; i <= C; i++) {
            while (top > 0 && h[stack[top - 1]] >= h[i]) {
                int height = h[stack[--top]];
                int width = top > 0 ? i - stack[top - 1] - 1 : i;
                if (height * width > best) best = height * width;
            }
            stack[top++] = i;
        }
    }
    free(h);
    free(stack);
    return best;
}
